import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const WIN = process.platform === 'win32'

/** 璇诲彇骞惰В鏋?JSON锛屽け璐ヨ繑鍥?null */
function readJson(file) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'))
  } catch {
    return null
  }
}

/** 瑙ｆ瀽瀹為檯鎵ц鐩綍锛氫紭鍏?PM_WORKSPACE锛屽叾娆?workspaces[0]锛屽啀鍏滃簳 zhi2-web-admin */
function resolveWorkspace() {
  const forced = (process.env.PM_WORKSPACE || '').trim()
  if (forced) {
    const dir = path.resolve(ROOT, forced)
    if (!fs.existsSync(path.join(dir, 'package.json'))) {
      fail(`PM_WORKSPACE=${forced}锛屼絾 ${dir} 涓嬫病鏈?package.json`)
    }
    return dir
  }

  const rootPkg = readJson(path.join(ROOT, 'package.json'))
  const workspaces = Array.isArray(rootPkg?.workspaces) ? rootPkg.workspaces : []

  for (const entry of workspaces) {
    // 鏀寔 glob锛坅pps/* 涔嬬被锛夛紝閫愪釜灞曞紑鍙栫涓€涓瓨鍦ㄧ殑
    const candidates = entry.includes('*')
      ? fs
          .readdirSync(ROOT, { withFileTypes: true })
          .filter((d) => d.isDirectory())
          .map((d) => d.name)
          .filter((name) => new RegExp(`^${entry.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '[^/]+')}$`).test(name))
      : [entry]

    for (const candidate of candidates) {
      const dir = path.resolve(ROOT, candidate)
      if (fs.existsSync(path.join(dir, 'package.json'))) return dir
    }
  }

  // 浠撳簱鏍硅嚜韬氨鏄簲鐢?  if (rootPkg?.scripts?.dev && !workspaces.length) return ROOT

  const fallback = path.join(ROOT, 'zhi2-web-admin')
  if (fs.existsSync(path.join(fallback, 'package.json'))) return fallback
  return ROOT
}

function usage() {
  console.log(`pm.mjs 鈥斺€?dev server 鍚姩鍣紙bun 浼樺厛銆乶pm 鍏滃簳锛?
鐢ㄦ硶:
  node scripts/pm.mjs [task] [args...]   # task 榛樿 dev

鐜鍙橀噺:
  PM=npm|bun        寮哄埗鎸囧畾鍖呯鐞嗗櫒锛堥粯璁? 鏈?bun 鐢?bun锛屽惁鍒?npm锛?  BUN_RUNTIME=1     浣跨敤 bun 杩愯鏃舵墽琛?vite锛坆un --bun run dev锛?  PM_DRY_RUN=1      鍙墦鍗板懡浠わ紝涓嶆墽琛?  PM_WORKSPACE=xx   鎸囧畾 workspace 鐩綍锛堥粯璁よ嚜鍔ㄦ帰娴嬶級

绀轰緥:
  npm run dev                     # 鑷姩閫夋嫨 bun 鎴?npm
  npm run dev:npm                 # 寮哄埗璧?npm
  npm run dev -- --port 8080      # 閫忎紶鍙傛暟缁?vite`)
}

function fail(msg) {
  console.error(`[pm] ${msg}`)
  process.exit(1)
}

function hasBun() {
  const r = spawnSync('bun', ['--version'], { stdio: 'ignore', shell: WIN })
  return r.status === 0
}

function resolveRunner() {
  const force = (process.env.PM || '').trim().toLowerCase()
  if (force === 'npm') return 'npm'
  if (force === 'bun') {
    if (!hasBun()) fail('PM=bun锛屼絾鏈娴嬪埌 bun銆傚畨瑁咃細https://bun.sh')
    return 'bun'
  }
  return hasBun() ? 'bun' : 'npm'
}

const argv = process.argv.slice(2)
if (argv[0] === '-h' || argv[0] === '--help') {
  usage()
  process.exit(0)
}

const WORKSPACE = resolveWorkspace()
const pm = resolveRunner()
const [task = 'dev', ...rawRest] = argv
// 鍏佽 `pm.mjs dev -- --port 8080` 杩欑鍐欐硶锛岄伩鍏嶅嚭鐜板弻閲?`--`
const rest = rawRest[0] === '--' ? rawRest.slice(1) : rawRest

let cmd
